referenceSolutions.javascript:
export function solve(calls) {
  let initialized = false,
    value = null,
    constructions = 0;
  const observations = calls.map((x) => {
    if (!initialized) {
      value = x;
      initialized = true;
      constructions++;
    }
    return { id: 1, value };
  });
  return { observations, constructions };
}

